cd . && python -c "
import numpy as np
L=open('init.xyz').read().split('\n')[2:]
E=[];P=[]
for l in L:
    if l.strip():
        s=l.split(); E.append(s[0]); P.append([float(x) for x in s[1:]])
P=np.array(P)
D=np.linalg.norm(P[:,None]-P[None],axis=-1)+np.eye(len(P))*99
idx=np.argwhere(D<1.0)
for i,j in idx:
    if i<j: print(i,E[i],j,E[j],round(D[i,j],3))
"
